  {},
  #"SYSTEM_SYSRULES_queryEntity_v2"(
    fetchtotalcount: false,
    entity: #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14141393",
    query: #"SYSTEM_SYSRULES_query"(
      paginginfo: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!pagingInfo),
        #"SYSTEM_SYSRULES_pagingInfo"(
          startIndex: 1,
          batchSize: -1,
          sort: #"SYSTEM_SYSRULES_sortInfo"(
            field: "clientId",
            ascending: true
